async function readAdminData(){
 const [variants,orders,profiles,productTypes,collections,designs,coupons]=await Promise.all([
  supabase.from('product_variants').select('id,sku,size,color_name,price_clp,active,product_models!inner(name,code)').order('sku'),
  supabase.from('orders').select('id,user_id,source,coupon_code,status,currency,subtotal_clp,shipping_clp,discount_clp,total_clp,created_at,submitted_at,shipping_address,price_snapshot,order_items(id,name_snapshot,sku_snapshot,print_sides,quantity,unit_price_clp,line_total_clp),order_status_history(id,status,note,created_at),payments(id,provider,provider_reference,status,amount_clp,confirmed_at)').order('created_at',{ascending:false}).limit(100),
  supabase.from('profiles').select('id',{count:'exact',head:true}),
  supabase.from('catalog_product_types').select('id,slug,name,active,sort_order,created_at').order('sort_order').order('name'),
  supabase.from('catalog_collections').select('id,product_type_id,slug,name,active,sort_order,created_at').order('sort_order').order('name'),
  supabase.from('catalog_designs').select('id,collection_id,slug,name,caption,artwork_path,sample_color,active,created_at').order('created_at',{ascending:false}),
  supabase.from('coupons').select('*').order('created_at',{ascending:false})
 ]);
 for(const result of [variants,orders,profiles,productTypes,collections,designs,coupons])if(result.error)throw result.error;
 const localOrders=import.meta.env.DEV?readLocalOrders():[];
 return {variants:variants.data||[],orders:[...localOrders,...(orders.data||[])].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)),profileCount:profiles.count||0,productTypes:productTypes.data||[],collections:collections.data||[],designs:designs.data||[],coupons:coupons.data||[]};
}

async function ensureBaseCatalog(){
 const {data:productTypes,error:productTypeError}=await supabase.from('catalog_product_types').select('id,slug');
 if(productTypeError)throw productTypeError;const polerasId=productTypes?.find(item=>item.slug==='poleras')?.id;if(!polerasId)throw new Error('Falta el producto Poleras en el catálogo.');
 const {data:existingCollections,error:collectionReadError}=await supabase.from('catalog_collections').select('id,slug');
 if(collectionReadError)throw collectionReadError;
 const existingSlugs=new Set((existingCollections||[]).map(item=>item.slug));
 const missingCollections=existingCollections?.length?[]:baseCollections.filter(item=>!existingSlugs.has(item.id)).map((item,index)=>({product_type_id:polerasId,slug:item.id,name:item.label,active:true,sort_order:(index+1)*10}));
 if(missingCollections.length){const {error}=await supabase.from('catalog_collections').upsert(missingCollections,{onConflict:'slug',ignoreDuplicates:true});if(error)throw error}
 const {data:allCollections,error:collectionRefreshError}=await supabase.from('catalog_collections').select('id,slug');
 if(collectionRefreshError)throw collectionRefreshError;
 const collectionIds=new Map((allCollections||[]).map(item=>[item.slug,item.id]));
 const {data:existingDesigns,error:designReadError}=await supabase.from('catalog_designs').select('slug');
 if(designReadError)throw designReadError;
 const existingDesignSlugs=new Set((existingDesigns||[]).map(item=>item.slug));
 const missingDesigns=existingDesigns?.length?[]:baseDesigns.filter(item=>!existingDesignSlugs.has(item.id)&&collectionIds.has(item.collection)).map(item=>({collection_id:collectionIds.get(item.collection),slug:item.id,name:item.name,caption:item.caption,artwork_path:`local:${item.id}`,sample_color:normalizeSampleColor(item.sampleColor),active:true}));
 if(missingDesigns.length){const {error}=await supabase.from('catalog_designs').upsert(missingDesigns,{onConflict:'slug',ignoreDuplicates:true});if(error)throw error}
 return {collections:missingCollections.length,designs:missingDesigns.length};
}

const routes=[['resumen','home','Resumen'],['productos','box','Productos'],['colecciones','layers','Colecciones'],['disenos','image','Diseños'],['pedidos','receipt','Pedidos'],['cupones','tag','Cupones'],['clientes','users','Clientes'],['analitica','chart','Analítica'],['configuracion','settings','Configuración']];
function currentRoute(){const route=location.hash.replace('#','');return routes.some(([id])=>id===route)?route:'resumen'}
function navMarkup(active){return routes.map(([id,iconName,label])=>`<a href="#${id}" class="${active===id?'active':''}${['resumen','productos','colecciones','disenos','pedidos','cupones'].includes(id)?'':' is-planned'}" ${active===id?'aria-current="page"':''}>${icon(iconName)}<span>${label}</span>${id==='pedidos'&&adminData.orders.length?`<b>${adminData.orders.length}</b>`:''}</a>`).join('')}
function pageHeading(eyebrow,title,copy,action=''){return `<div class="admin-page-heading"><div><span class="admin-eyebrow">${eyebrow}</span><h1>${title}</h1><p>${copy}</p></div>${action}</div>`}
function shell(content,active){
 const initial=safe((sessionUser.email||'A').slice(0,1).toUpperCase());
 root.innerHTML=`<div class="admin-layout"><aside class="admin-sidebar"><a class="admin-brand" href="/">droska<span>*</span></a><nav aria-label="Administración">${navMarkup(active)}</nav><div class="admin-sidebar-note"><strong>Tu tienda,<br>sin límites.</strong><p>Diseños que se visten de ideas.</p><span aria-hidden="true">✳</span></div></aside><div class="admin-workspace"><header class="admin-topbar"><label class="admin-search">${icon('search')}<span class="sr-only">Buscar en el panel</span><input type="search" placeholder="Buscar en esta vista…" id="admin-search"></label><div class="admin-account"><span class="admin-avatar">${initial}</span><span><strong>Administración</strong><small>${safe(sessionUser.email)}</small></span><button type="button" id="admin-logout" aria-label="Cerrar sesión">${icon('logout')}</button></div></header><main class="admin-main">${content}</main></div></div><div class="admin-toast" role="status" aria-live="polite"></div>`;
 root.querySelector('#admin-logout').onclick=logout;
 root.querySelector('#admin-search').addEventListener('input',event=>filterCurrentView(event.target.value));
}
function toast(message){const node=root.querySelector('.admin-toast');if(!node)return;node.textContent=message;node.classList.add('visible');setTimeout(()=>node.classList.remove('visible'),2200)}
function filterCurrentView(query){const normalized=query.trim().toLowerCase();root.querySelectorAll('[data-admin-searchable]').forEach(item=>{item.hidden=Boolean(normalized&&!item.dataset.adminSearchable.includes(normalized))})}

