function openCollectionDialog(collection){
 const dialog=root.querySelector('#collection-dialog');const form=root.querySelector('#collection-form');form.reset();form.elements.id.value=collection?.id||'';form.elements.product_type_id.value=collection?.product_type_id||adminData.productTypes.find(item=>item.slug==='poleras')?.id||'';form.elements.name.value=collection?.name||'';form.elements.slug.value=collection?.slug||'';form.elements.sort_order.value=collection?.sort_order??adminData.collections.length;form.elements.active.checked=collection?.active??true;root.querySelector('#collection-dialog-title').textContent=collection?'Editar colección':'Nueva colección';dialog.showModal();form.elements.name.focus();if(collection)form.elements.name.select();
}
function wireCollections(){
 const dialog=root.querySelector('#collection-dialog');const form=root.querySelector('#collection-form');const deleteDialog=root.querySelector('#delete-collection-dialog');const deleteForm=deleteDialog.querySelector('form');const name=form.elements.name;const slug=form.elements.slug;let slugTouched=false;
 root.querySelector('#new-collection').onclick=()=>openCollectionDialog();root.querySelector('.dialog-close').onclick=()=>dialog.close();root.querySelector('.dialog-cancel').onclick=()=>dialog.close();
 slug.addEventListener('input',()=>{slugTouched=true});name.addEventListener('input',()=>{if(!slugTouched)slug.value=slugify(name.value)});
 root.querySelectorAll('[data-edit-collection]').forEach(button=>button.onclick=()=>openCollectionDialog(adminData.collections.find(item=>item.id===Number(button.dataset.editCollection))));
 root.querySelectorAll('[data-toggle-collection]').forEach(button=>button.onclick=async()=>{const collection=adminData.collections.find(item=>item.id===Number(button.dataset.toggleCollection));button.disabled=true;const {error}=await supabase.from('catalog_collections').update({active:!collection.active}).eq('id',collection.id);if(error){button.disabled=false;return toast(`No se pudo cambiar el estado: ${error.message}`)}await refreshData('Estado actualizado.',true)});
 root.querySelectorAll('[data-delete-collection]').forEach(button=>button.onclick=()=>{const collection=adminData.collections.find(item=>item.id===Number(button.dataset.deleteCollection));if(!collection)return;deleteForm.elements.collection_id.value=collection.id;deleteDialog.querySelector('[data-delete-name]').textContent=`“${collection.name}”`;deleteDialog.showModal();deleteDialog.querySelector('[data-delete-cancel]').focus()});
 deleteDialog.querySelectorAll('[data-delete-cancel]').forEach(button=>button.onclick=()=>deleteDialog.close());
 deleteForm.onsubmit=async event=>{event.preventDefault();const button=event.submitter,status=deleteForm.querySelector('.admin-form-status'),id=Number(deleteForm.elements.collection_id.value);button.disabled=true;button.textContent='Eliminando…';const {error}=await supabase.from('catalog_collections').delete().eq('id',id);if(error){button.disabled=false;button.textContent='Eliminar colección';status.textContent=error.code==='23503'?'La colección todavía contiene diseños. Muévelos o elimínalos primero.':error.message;return}deleteDialog.close();await refreshData('Colección eliminada.',true)};
 form.onsubmit=async event=>{event.preventDefault();const button=event.submitter;const status=form.querySelector('.admin-form-status');const values=new FormData(form);const payload={product_type_id:Number(values.get('product_type_id')),name:String(values.get('name')).trim(),slug:slugify(values.get('slug')),sort_order:Number(values.get('sort_order'))||0,active:values.get('active')==='on'};if(!payload.product_type_id||!payload.name||!payload.slug){status.textContent='Completa producto, nombre y slug.';return}button.disabled=true;button.textContent='Guardando…';const id=Number(values.get('id'));const query=id?supabase.from('catalog_collections').update(payload).eq('id',id):supabase.from('catalog_collections').insert(payload);const {error}=await query;if(error){button.disabled=false;button.textContent='Guardar colección';status.textContent=error.code==='23505'?'Ya existe una colección con ese slug.':error.message;return}dialog.close();await refreshData(id?'Colección actualizada.':'Colección creada.',true)};
}

const collectionName=id=>adminData.collections.find(item=>item.id===id)?.name||'Sin colección';
function designPreview(design){
 const localDesign=design.artwork_path?.startsWith('local:')?baseDesigns.find(item=>item.id===design.slug):null;
 const src=localDesign?artworkUrl(localDesign):design.artwork_path;
 return src?`<img src="${safe(src)}" alt="Vista previa de ${safe(design.name)}">`:`<span>${icon('image')}</span>`;
}
function designsView(){
 const rows=adminData.designs.map(design=>{const color=normalizeSampleColor(design.sample_color),colorName=sampleShirtColors.find(item=>item.value===color)?.label||'Blanco';return `<tr data-admin-searchable="${safe(`${design.name} ${design.slug} ${collectionName(design.collection_id)} ${colorName}`.toLowerCase())}"><td><div class="admin-design-thumb">${designPreview(design)}</div><div class="admin-design-name"><strong>${safe(design.name)}</strong><small>${safe(design.caption||'Sin descripción.')}</small></div></td><td><span class="admin-collection-label">${safe(collectionName(design.collection_id))}</span></td><td><span class="admin-sample-swatch" style="--sample-color:${color}"><i aria-hidden="true"></i>${safe(colorName)}</span></td><td><code>/${safe(design.slug)}</code></td><td><span class="status-pill ${design.active?'is-active':'is-hidden'}">${design.active?'Activo':'Oculto'}</span></td><td><div class="row-actions"><button type="button" data-edit-design="${design.id}">Editar</button><button type="button" data-toggle-design="${design.id}">${design.active?'Ocultar':'Activar'}</button><button type="button" class="admin-danger-link" data-delete-design="${design.id}">Eliminar</button></div></td></tr>`}).join('');
 const action=`<button type="button" class="admin-primary" id="new-design">${icon('plus')} Nuevo diseño</button>`;
 const options=adminData.collections.map(collection=>`<option value="${collection.id}">${safe(collection.name)}</option>`).join('');
 const list=rows?`<section class="admin-panel admin-design-panel"><div class="admin-panel-head"><div><h2>Todos los diseños</h2><p>${adminData.designs.length} en total · ${adminData.designs.filter(item=>item.active).length} activos</p></div></div><div class="admin-table-wrap"><table class="admin-table admin-design-table"><thead><tr><th>Diseño</th><th>Colección</th><th>Polera muestra</th><th>Slug</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${rows}</tbody></table></div></section>`:'<section class="admin-panel admin-empty"><strong>Aún no hay diseños.</strong><p>Carga el primero para comenzar tu catálogo.</p></section>';
 const colorOptions=sampleShirtColors.map((color,index)=>`<label class="admin-color-option"><input type="radio" name="sample_color" value="${color.value}" ${index===0?'checked':''} required><i style="--sample-color:${color.value}" aria-hidden="true"></i><span>${safe(color.label)}</span></label>`).join('');
 const content=`${pageHeading('CATÁLOGO','Diseños.','Carga piezas y asígnalas a una colección. Los diseños activos aparecen en la tienda.',action)}${list}<dialog class="admin-dialog admin-design-dialog" id="design-dialog"><form method="dialog" id="design-form"><div class="dialog-title"><div><span class="admin-eyebrow">CATÁLOGO</span><h2 id="design-dialog-title">Nuevo diseño</h2></div><button type="button" class="dialog-close" aria-label="Cerrar">×</button></div><input type="hidden" name="id"><label>Colección<select name="collection_id" required><option value="">Selecciona una colección</option>${options}</select></label><label>Nombre<input name="name" required maxlength="80" placeholder="Ej. Reto lunar"></label><label>Slug<input name="slug" required maxlength="80" pattern="[a-z0-9-]+" placeholder="reto-lunar"><small>Identificador único del diseño.</small></label><label>Descripción<textarea name="caption" maxlength="180" rows="3" placeholder="Una frase breve para la tarjeta."></textarea></label><fieldset class="admin-sample-colors"><legend>Color de polera para la muestra 3D</legend><p>Elige el tono que mejor haga lucir este diseño en el catálogo.</p><div>${colorOptions}</div></fieldset><label class="admin-file"><span>Archivo del diseño</span><input name="artwork" type="file" accept="image/png,image/jpeg,image/webp"><small>PNG transparente recomendado. JPG o WebP, máximo 10 MB.</small><output id="design-file-name">Ningún archivo seleccionado.</output></label><div class="design-file-preview" id="design-file-preview" hidden><img alt="Vista previa del archivo seleccionado"></div><label class="admin-check"><input name="active" type="checkbox" checked><span>Mostrar este diseño en la tienda</span></label><div class="dialog-actions"><button type="button" class="admin-secondary dialog-cancel">Cancelar</button><button type="submit" class="admin-primary">Publicar diseño</button></div><p class="admin-form-status" role="alert"></p></form></dialog><dialog class="admin-dialog admin-confirm-dialog" id="delete-design-dialog"><form method="dialog"><div class="dialog-title"><div><span class="admin-eyebrow">ACCIÓN PERMANENTE</span><h2>Eliminar diseño</h2></div><button type="button" class="dialog-close" data-delete-design-cancel aria-label="Cerrar">×</button></div><p>Vas a eliminar <strong data-delete-design-name></strong> y su archivo del catálogo. Esta acción no se puede deshacer.</p><input type="hidden" name="design_id"><div class="dialog-actions"><button type="button" class="admin-secondary" data-delete-design-cancel>Cancelar</button><button type="submit" class="admin-danger">Eliminar diseño</button></div><p class="admin-form-status" role="alert"></p></form></dialog>`;
 shell(content,'disenos');root.querySelector('.admin-file small').textContent='PNG transparente recomendado. Hasta 50 MB de origen; optimizamos automáticamente si supera 10 MB o 4.800 px.';wireDesigns();
}
function validateArtwork(file,required,maxBytes=CATALOG_SOURCE_MAX_BYTES){
 if(!file?.size)return required?'Selecciona un archivo para el diseño.':'';
 if(!['image/png','image/jpeg','image/webp'].includes(file.type))return 'Usa un archivo PNG, JPG o WebP.';
 if(file.size>maxBytes)return `El archivo supera el máximo de ${Math.round(maxBytes/1024/1024)} MB.`;
 return '';
}
const fileSizeLabel=bytes=>bytes<1024*1024?`${Math.round(bytes/1024)} KB`:`${(bytes/1024/1024).toFixed(1)} MB`;
async function imageDimensions(file){
 const url=URL.createObjectURL(file);const image=new Image();image.src=url;
 try{await image.decode();return {image,width:image.naturalWidth,height:image.naturalHeight,url}}catch(error){URL.revokeObjectURL(url);throw error}
}
const canvasBlob=(canvas,type,quality)=>new Promise(resolve=>canvas.toBlob(resolve,type,quality));
async function optimizeCatalogArtwork(file){
 const decoded=await imageDimensions(file);const largest=Math.max(decoded.width,decoded.height);
 if(file.size<=CATALOG_MAX_BYTES&&largest<=CATALOG_MAX_DIMENSION){URL.revokeObjectURL(decoded.url);return {file,optimized:false,width:decoded.width,height:decoded.height}}
 const scale=Math.min(1,CATALOG_MAX_DIMENSION/largest);const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(decoded.width*scale));canvas.height=Math.max(1,Math.round(decoded.height*scale));const context=canvas.getContext('2d',{alpha:true});context.imageSmoothingEnabled=true;context.imageSmoothingQuality='high';context.drawImage(decoded.image,0,0,canvas.width,canvas.height);URL.revokeObjectURL(decoded.url);
 let blob=await canvasBlob(canvas,'image/webp',.9);
 if(blob?.size>CATALOG_MAX_BYTES)blob=await canvasBlob(canvas,'image/webp',.78);
 if(blob?.size>CATALOG_MAX_BYTES)blob=await canvasBlob(canvas,'image/webp',.65);
 if(!blob)throw new Error('El navegador no pudo optimizar esta imagen.');
 const basename=file.name.replace(/\.[^.]+$/,'');
 return {file:new File([blob],`${basename}.webp`,{type:'image/webp',lastModified:Date.now()}),optimized:true,width:canvas.width,height:canvas.height};
}
function publicArtworkUrl(path){return supabase.storage.from(CATALOG_BUCKET).getPublicUrl(path).data.publicUrl}
function storagePathFromUrl(url){const marker=`/storage/v1/object/public/${CATALOG_BUCKET}/`;return url?.includes(marker)?decodeURIComponent(url.split(marker)[1]):''}
function openDesignDialog(design){
 const dialog=root.querySelector('#design-dialog');const form=root.querySelector('#design-form');form.reset();form.elements.id.value=design?.id||'';form.elements.collection_id.value=design?.collection_id||'';form.elements.name.value=design?.name||'';form.elements.slug.value=design?.slug||'';form.elements.caption.value=design?.caption||'';form.elements.active.checked=design?.active??true;form.elements.artwork.required=!design;const sampleColor=normalizeSampleColor(design?.sample_color);const colorInput=form.querySelector(`[name="sample_color"][value="${sampleColor}"]`);if(colorInput)colorInput.checked=true;root.querySelector('#design-dialog-title').textContent=design?'Editar diseño':'Nuevo diseño';form.querySelector('[type="submit"]').textContent=design?'Guardar cambios':'Publicar diseño';const preview=root.querySelector('#design-file-preview');const previewImage=preview.querySelector('img');if(design?.artwork_path&&!design.artwork_path.startsWith('local:')){previewImage.src=design.artwork_path;preview.hidden=false}else{previewImage.removeAttribute('src');preview.hidden=true}root.querySelector('#design-file-name').textContent=design?'Puedes conservar el archivo actual.':'Ningún archivo seleccionado.';dialog.showModal();form.elements.collection_id.focus();
}
async function submitDesign(form,fileInput,event){
 event.preventDefault();const button=event.submitter;const status=form.querySelector('.admin-form-status');const values=new FormData(form);const id=Number(values.get('id'));const current=id?adminData.designs.find(item=>item.id===id):null;const sourceFile=fileInput.files[0];const validation=validateArtwork(sourceFile,!current);if(validation){status.textContent=validation;return}
 const payload={collection_id:Number(values.get('collection_id')),name:String(values.get('name')).trim(),slug:slugify(values.get('slug')),caption:String(values.get('caption')).trim()||null,sample_color:normalizeSampleColor(values.get('sample_color')),active:values.get('active')==='on'};if(!payload.collection_id||!payload.name||!payload.slug){status.textContent='Completa colección, nombre y slug.';return}
 button.disabled=true;status.textContent='';let uploadedPath='';
 try{
  let file=sourceFile;
  if(sourceFile){button.textContent='Optimizando imagen…';const result=await optimizeCatalogArtwork(sourceFile);file=result.file;const optimizedValidation=validateArtwork(file,true,CATALOG_MAX_BYTES);if(optimizedValidation)throw new Error('No logramos reducir la imagen bajo 10 MB. Prueba exportándola con menos resolución.');status.textContent=result.optimized?`Optimizada: ${fileSizeLabel(sourceFile.size)} → ${fileSizeLabel(file.size)} · ${result.width} × ${result.height} px`:`Archivo listo: ${fileSizeLabel(file.size)} · ${result.width} × ${result.height} px`}
  if(file){button.textContent='Subiendo archivo…';const extension=file.name.split('.').pop().toLowerCase();const collection=adminData.collections.find(item=>item.id===payload.collection_id);uploadedPath=`${collection.slug}/${payload.slug}-${Date.now()}.${extension}`;const {error:uploadError}=await supabase.storage.from(CATALOG_BUCKET).upload(uploadedPath,file,{cacheControl:'3600',contentType:file.type,upsert:false});if(uploadError)throw uploadError;payload.artwork_path=publicArtworkUrl(uploadedPath)}
  button.textContent='Guardando…';const query=id?supabase.from('catalog_designs').update(payload).eq('id',id):supabase.from('catalog_designs').insert(payload);const {error}=await query;if(error)throw error;
  if(file&&current){const oldPath=storagePathFromUrl(current.artwork_path);if(oldPath)await supabase.storage.from(CATALOG_BUCKET).remove([oldPath])}
  form.closest('dialog').close();await refreshData(id?'Diseño actualizado.':'Diseño publicado.',true);
 }catch(error){if(uploadedPath)await supabase.storage.from(CATALOG_BUCKET).remove([uploadedPath]);button.disabled=false;button.textContent=id?'Guardar cambios':'Publicar diseño';status.textContent=error.message.includes('Bucket not found')?'Falta habilitar el almacenamiento del catálogo en Supabase.':error.code==='23505'?'Ya existe un diseño con ese slug.':`No pudimos guardar: ${error.message}`}
}
function wireDesigns(){
 const dialog=root.querySelector('#design-dialog');const form=root.querySelector('#design-form');const deleteDialog=root.querySelector('#delete-design-dialog');const deleteForm=deleteDialog.querySelector('form');const name=form.elements.name;const slug=form.elements.slug;const fileInput=form.elements.artwork;let slugTouched=false;
 root.querySelector('#new-design').onclick=()=>openDesignDialog();root.querySelector('.dialog-close').onclick=()=>dialog.close();root.querySelector('.dialog-cancel').onclick=()=>dialog.close();slug.addEventListener('input',()=>{slugTouched=true});name.addEventListener('input',()=>{if(!slugTouched)slug.value=slugify(name.value)});
 root.querySelectorAll('[data-edit-design]').forEach(button=>button.onclick=()=>openDesignDialog(adminData.designs.find(item=>item.id===Number(button.dataset.editDesign))));
 root.querySelectorAll('[data-toggle-design]').forEach(button=>button.onclick=async()=>{const design=adminData.designs.find(item=>item.id===Number(button.dataset.toggleDesign));button.disabled=true;const {error}=await supabase.from('catalog_designs').update({active:!design.active}).eq('id',design.id);if(error){button.disabled=false;return toast(`No se pudo cambiar el estado: ${error.message}`)}await refreshData('Estado del diseño actualizado.',true)});
 root.querySelectorAll('[data-delete-design]').forEach(button=>button.onclick=()=>{const design=adminData.designs.find(item=>item.id===Number(button.dataset.deleteDesign));if(!design)return;deleteForm.elements.design_id.value=design.id;deleteDialog.querySelector('[data-delete-design-name]').textContent=`“${design.name}”`;deleteDialog.showModal();deleteDialog.querySelector('[data-delete-design-cancel]').focus()});
 deleteDialog.querySelectorAll('[data-delete-design-cancel]').forEach(button=>button.onclick=()=>deleteDialog.close());
 deleteForm.onsubmit=async event=>{event.preventDefault();const button=event.submitter,status=deleteForm.querySelector('.admin-form-status'),id=Number(deleteForm.elements.design_id.value),design=adminData.designs.find(item=>item.id===id);button.disabled=true;button.textContent='Eliminando…';const {error}=await supabase.from('catalog_designs').delete().eq('id',id);if(error){button.disabled=false;button.textContent='Eliminar diseño';status.textContent=error.code==='23503'?'Este diseño está asociado a un carro o pedido y no se puede eliminar. Puedes ocultarlo.':error.message;return}const path=storagePathFromUrl(design?.artwork_path);let storageError=null;if(path)({error:storageError}=await supabase.storage.from(CATALOG_BUCKET).remove([path]));deleteDialog.close();await refreshData(storageError?'Diseño eliminado; quedó un archivo pendiente de limpieza.':'Diseño eliminado.',true)};
 fileInput.addEventListener('change',()=>{const file=fileInput.files[0];root.querySelector('#design-file-name').textContent=file?`${file.name} · ${fileSizeLabel(file.size)}`:'Ningún archivo seleccionado.';const preview=root.querySelector('#design-file-preview');if(!file){preview.hidden=true;return}preview.querySelector('img').src=URL.createObjectURL(file);preview.hidden=false});
 form.onsubmit=event=>submitDesign(form,fileInput,event);
}

function adminOrderStepper(order){const steps=orderSteps(order),current=orderProgressIndex(order.status,order);return `<ol class="admin-order-progress${order.status==='cancelled'?' is-cancelled':''}" style="--order-step-count:${steps.length}" aria-label="Avance del pedido">${steps.map((step,index)=>`<li class="${index<current?'complete':index===current?'current':''}"><span aria-hidden="true">${index<current?'✓':String(index+1).padStart(2,'0')}</span><strong>${safe(step.label)}</strong></li>`).join('')}</ol>`}
function orderCustomer(order){return order.shipping_address?.customer||{}}
function orderCustomerName(order){const customer=orderCustomer(order);return [customer.first_name,customer.last_name].filter(Boolean).join(' ')||'Cliente sin nombre'}
function orderDestination(order){const address=order.shipping_address||{};return address.fulfillment==='pickup'?'Retiro en tienda':[address.address,address.address_extra,address.commune,address.region].filter(Boolean).join(', ')||'Dirección pendiente'}
function orderCard(order){const items=order.order_items||[],units=items.reduce((sum,item)=>sum+item.quantity,0),isDemo=Boolean(order.price_snapshot?.demo),search=[order.id,orderCustomerName(order),orderCustomer(order).email,order.status,...items.map(item=>item.name_snapshot)].join(' ').toLowerCase();return `<article class="admin-kanban-card" data-admin-searchable="${safe(search)}"><div class="admin-kanban-card-top"><span class="admin-eyebrow">#${safe(order.id)}</span><div>${order.source==='manual'?'<span class="admin-source-pill">Manual</span>':''}${isDemo?'<span class="admin-demo-pill">Simulado</span>':''}</div></div><h3>${safe(orderCustomerName(order))}</h3><p>${safe(order.shipping_address?.fulfillment==='pickup'?'Retiro en tienda':'Despacho')} · ${units} ${units===1?'unidad':'unidades'}</p><div class="admin-kanban-card-meta"><span class="status-pill">${safe(orderStatusLabel(order.status))}</span><strong>${money(order.total_clp)}</strong></div><small>${date(order.created_at)}</small><button type="button" class="admin-card-open" data-open-order="${safe(order.id)}">Ver pedido <span>→</span></button></article>`}
function orderDetailMarkup(order){const address=order.shipping_address||{},customer=orderCustomer(order),items=order.order_items||[],payment=(order.payments||[])[0],next=nextOrderStatus(order.status,order),phone=String(customer.phone||'').replace(/[^\d+]/g,''),wa=String(customer.phone||'').replace(/\D/g,''),history=[...(order.order_status_history||[])].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));return `<div class="dialog-title"><div><span class="admin-eyebrow">PEDIDO #${safe(order.id)} · ${order.source==='manual'?'MANUAL':'ONLINE'}</span><h2>${safe(orderCustomerName(order))}</h2></div><button type="button" class="dialog-close" aria-label="Cerrar">×</button></div>${adminOrderStepper(order)}<div class="admin-order-contact"><a href="tel:${safe(phone)}">Llamar</a><a href="https://wa.me/${safe(wa)}" target="_blank" rel="noreferrer">WhatsApp</a><a href="mailto:${safe(customer.email||'')}">Email</a></div><div class="admin-order-detail-grid"><section><span class="admin-eyebrow">CLIENTE Y ENTREGA</span><dl><div><dt>Nombre</dt><dd>${safe(orderCustomerName(order))}</dd></div><div><dt>Email</dt><dd>${safe(customer.email||'No informado')}</dd></div><div><dt>Teléfono</dt><dd>${safe(customer.phone||'No informado')}</dd></div><div><dt>${address.fulfillment==='pickup'?'Entrega':'Dirección'}</dt><dd>${safe(orderDestination(order))}</dd></div>${address.notes?`<div><dt>Indicaciones</dt><dd>${safe(address.notes)}</dd></div>`:''}</dl></section><section><span class="admin-eyebrow">COBRO</span><dl><div><dt>Subtotal</dt><dd>${money(order.subtotal_clp)}</dd></div><div><dt>Despacho</dt><dd>${order.shipping_clp?money(order.shipping_clp):'Gratis'}</dd></div>${order.discount_clp?`<div><dt>Descuento ${safe(order.coupon_code||'')}</dt><dd>−${money(order.discount_clp)}</dd></div>`:''}<div><dt>Total</dt><dd><strong>${money(order.total_clp)}</strong></dd></div><div><dt>Pago</dt><dd>${payment?`${safe(payment.provider)} · ${safe(payment.status)}`:'Pedido manual'}</dd></div></dl></section></div><section class="admin-order-items"><span class="admin-eyebrow">PRODUCTOS</span>${items.map(item=>`<div><span><strong>${safe(item.name_snapshot)}</strong><small>${safe(item.sku_snapshot||'Sin SKU')} · ${safe(item.print_sides)} · ${item.quantity} un.</small></span><b>${money(item.line_total_clp)}</b></div>`).join('')||'<p>Sin productos registrados.</p>'}</section>${history.length?`<section class="admin-order-history-wrap"><span class="admin-eyebrow">HISTORIAL</span><ul class="admin-order-history">${history.map(item=>`<li><span>${safe(orderStatusLabel(item.status))}</span><time datetime="${safe(item.created_at)}">${date(item.created_at)}</time></li>`).join('')}</ul></section>`:''}<div class="dialog-actions admin-order-dialog-actions"><button type="button" class="admin-secondary" data-print-order="${safe(order.id)}">Imprimir etiqueta</button>${next?`<button type="button" class="admin-primary" data-order-id="${safe(order.id)}" data-next-status="${safe(next.status)}">${safe(next.adminAction)}</button>`:'<span class="admin-order-complete">✓ Operación terminada</span>'}</div>`}
function manualOrderDialog(){return `<dialog class="admin-dialog admin-manual-dialog" id="manual-order-dialog"><form id="manual-order-form"><div class="dialog-title"><div><span class="admin-eyebrow">VENTA PRESENCIAL</span><h2>Nuevo pedido manual</h2></div><button type="button" class="dialog-close" aria-label="Cerrar">×</button></div><div class="admin-form-grid"><label>Nombre<input name="first_name" required></label><label>Apellido<input name="last_name"></label><label>Email<input name="email" type="email"></label><label>Teléfono<input name="phone" type="tel" required></label><label>Entrega<select name="fulfillment"><option value="pickup">Retiro en tienda</option><option value="delivery">Despacho</option></select></label><label>Región<input name="region"></label><label>Comuna<input name="commune"></label><label>Dirección<input name="address"></label><label class="admin-form-wide">Producto<input name="item_name" required placeholder="Ej. Polera básica personalizada"></label><label>Cantidad<input name="quantity" type="number" min="1" max="20" value="1" required></label><label>Precio unitario<input name="unit_price" type="number" min="0" step="10" required></label><label class="admin-form-wide">Indicaciones<textarea name="notes" rows="2"></textarea></label></div><div class="dialog-actions"><button type="button" class="admin-secondary dialog-cancel">Cancelar</button><button type="submit" class="admin-primary">Crear pedido</button></div><p class="admin-form-status" role="alert"></p></form></dialog>`}
function ordersView(){const orders=adminData.orders,columns=[['incoming','Pedido ingresado'],['processing','Pedido en proceso'],['handoff','Para entrega / despachado']];const action=`<button type="button" class="admin-primary" id="new-manual-order">${icon('plus')} Pedido manual</button>`;const board=columns.map(([stage,label])=>{const stageOrders=orders.filter(order=>orderKanbanStage(order.status)===stage);return `<section class="admin-kanban-column"><header><h2>${label}</h2><span>${stageOrders.length}</span></header><div>${stageOrders.map(orderCard).join('')||'<p class="admin-kanban-empty">No hay pedidos en esta etapa.</p>'}</div></section>`}).join('');const content=`${pageHeading('OPERACIÓN','Pedidos.','Vista resumida por etapa. Abre un pedido para contactar, revisar datos, avanzar o imprimir su etiqueta.',action)}<section class="admin-orders-toolbar"><strong>${orders.length} ${orders.length===1?'pedido':'pedidos'}</strong><span>${orders.filter(order=>order.source==='manual').length} manuales</span></section><section class="admin-kanban">${board}</section><dialog class="admin-dialog admin-order-dialog" id="order-dialog"><div id="order-dialog-content"></div></dialog>${manualOrderDialog()}`;shell(content,'pedidos');wireOrders()}
async function advanceOrder(button){const order=adminData.orders.find(item=>String(item.id)===button.dataset.orderId),status=button.dataset.nextStatus,label=orderStatusLabel(status);if(!order||!window.confirm(`¿Avanzar el pedido #${order.id} a “${label}”?`))return;button.disabled=true;button.textContent='Actualizando…';if(import.meta.env.DEV&&String(order.id).startsWith('LOCAL-')){const orders=readLocalOrders(),local=orders.find(item=>item.id===order.id);if(local){const now=new Date().toISOString();local.status=status;local.order_status_history=[...(local.order_status_history||[]),{id:`${order.id}-${now}`,status,note:'Estado actualizado en el panel local.',created_at:now}];localStorage.setItem(LOCAL_DEMO_ORDERS_KEY,JSON.stringify(orders));await refreshData(`${label} · actualización local.`);return}}const {data,error}=await supabase.functions.invoke('update-order-status',{body:{orderId:order.id,status}});if(error||data?.error){const {error:updateError}=await supabase.from('orders').update({status,updated_at:new Date().toISOString()}).eq('id',order.id).eq('status',order.status);if(updateError){button.disabled=false;button.textContent=nextOrderStatus(order.status,order)?.adminAction||'Reintentar';toast(data?.error||'No pudimos actualizar el pedido.');return}await refreshData(`${label} · estado actualizado; email pendiente de configurar.`);return}await refreshData(data.email?.sent?`${label} · email enviado al cliente.`:`${label} · estado actualizado; email pendiente.`)}
function printOrderLabel(order){const customer=orderCustomer(order),popup=window.open('','_blank','width=760,height=720');if(!popup)return toast('Permite ventanas emergentes para imprimir.');popup.document.write(`<!doctype html><html lang="es"><head><title>Etiqueta pedido ${safe(order.id)}</title><style>body{font:16px Arial;padding:28px;color:#171914}.label{border:3px solid;padding:28px;max-width:620px}.brand{font-size:30px;font-weight:800}.id{font-size:22px;margin:24px 0}.name{font-size:28px;font-weight:800}.address{font-size:20px;line-height:1.45;margin:14px 0}.meta{border-top:1px solid;margin-top:20px;padding-top:14px}@media print{body{padding:0}.label{border:2px solid}}</style></head><body><div class="label"><div class="brand">droska SHIRT</div><div class="id">PEDIDO #${safe(order.id)}</div><div class="name">${safe(orderCustomerName(order))}</div><div class="address">${safe(orderDestination(order))}</div><div>${safe(customer.phone||'Sin teléfono')}<br>${safe(customer.email||'')}</div><div class="meta">${order.shipping_address?.fulfillment==='pickup'?'RETIRO EN TIENDA':'DESPACHO'} · ${(order.order_items||[]).reduce((sum,item)=>sum+item.quantity,0)} unidades</div></div><script>window.print()<\/script></body></html>`);popup.document.close()}
async function submitManualOrder(event){event.preventDefault();const form=event.currentTarget,data=new FormData(form),button=event.submitter,quantity=Number(data.get('quantity')),unitPrice=Number(data.get('unit_price')),total=quantity*unitPrice,fulfillment=String(data.get('fulfillment'));button.disabled=true;button.textContent='Creando…';const shippingAddress={fulfillment,customer:{first_name:String(data.get('first_name')).trim(),last_name:String(data.get('last_name')).trim(),email:String(data.get('email')).trim(),phone:String(data.get('phone')).trim()},region:String(data.get('region')).trim(),commune:String(data.get('commune')).trim(),address:String(data.get('address')).trim(),notes:String(data.get('notes')).trim()};const {data:order,error}=await supabase.from('orders').insert({user_id:null,source:'manual',status:'paid',subtotal_clp:total,shipping_clp:0,discount_clp:0,total_clp:total,shipping_address:shippingAddress,price_snapshot:{manual:true},submitted_at:new Date().toISOString()}).select('id').single();if(error){button.disabled=false;button.textContent='Crear pedido';form.querySelector('.admin-form-status').textContent=error.message;return}const {error:itemError}=await supabase.from('order_items').insert({order_id:order.id,name_snapshot:String(data.get('item_name')).trim(),sku_snapshot:'MANUAL',print_sides:'front',quantity,unit_price_clp:unitPrice,line_total_clp:total});if(itemError){await supabase.from('orders').delete().eq('id',order.id);button.disabled=false;button.textContent='Crear pedido';form.querySelector('.admin-form-status').textContent=itemError.message;return}await supabase.from('order_status_history').insert({order_id:order.id,status:'paid',note:'Pedido ingresado manualmente en el panel.'});form.closest('dialog').close();await refreshData('Pedido manual creado.')}
function wireOrders(){const dialog=root.querySelector('#order-dialog'),content=root.querySelector('#order-dialog-content');root.querySelectorAll('[data-open-order]').forEach(button=>button.onclick=()=>{const order=adminData.orders.find(item=>String(item.id)===button.dataset.openOrder);content.innerHTML=orderDetailMarkup(order);dialog.showModal();content.querySelector('.dialog-close').onclick=()=>dialog.close();content.querySelector('[data-next-status]')?.addEventListener('click',event=>advanceOrder(event.currentTarget));content.querySelector('[data-print-order]')?.addEventListener('click',()=>printOrderLabel(order))});const manual=root.querySelector('#manual-order-dialog');root.querySelector('#new-manual-order').onclick=()=>manual.showModal();manual.querySelector('.dialog-close').onclick=()=>manual.close();manual.querySelector('.dialog-cancel').onclick=()=>manual.close();manual.querySelector('form').onsubmit=submitManualOrder}

function couponLabel(coupon){return coupon.kind==='percent'?`${coupon.value}%`:`${money(coupon.value)}`}
function couponsView(){const rows=adminData.coupons.map(coupon=>`<tr data-admin-searchable="${safe(`${coupon.code} ${coupon.description||''}`.toLowerCase())}"><td><strong>${safe(coupon.code)}</strong><small>${safe(coupon.description||'Sin descripción')}</small></td><td>${couponLabel(coupon)}</td><td>${money(coupon.min_subtotal_clp)}</td><td>${coupon.used_count}${coupon.max_uses?` / ${coupon.max_uses}`:''}</td><td><span class="status-pill ${coupon.active?'is-active':'is-hidden'}">${coupon.active?'Activo':'Pausado'}</span></td><td><button type="button" class="admin-secondary" data-toggle-coupon="${coupon.id}">${coupon.active?'Pausar':'Activar'}</button></td></tr>`).join('');const action=`<button class="admin-primary" type="button" id="new-coupon">${icon('plus')} Nuevo cupón</button>`;const content=`${pageHeading('VENTAS','Cupones.','Crea descuentos con vigencia, compra mínima y límite de usos.',action)}<section class="admin-panel"><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Código</th><th>Descuento</th><th>Compra mínima</th><th>Usos</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${rows}</tbody></table></div></section><dialog class="admin-dialog" id="coupon-dialog"><form id="coupon-form"><div class="dialog-title"><div><span class="admin-eyebrow">DESCUENTO</span><h2>Nuevo cupón</h2></div><button type="button" class="dialog-close" aria-label="Cerrar">×</button></div><label>Código<input name="code" required minlength="3" maxlength="32" placeholder="BIENVENIDA10"></label><label>Descripción<input name="description" maxlength="100"></label><div class="admin-form-grid"><label>Tipo<select name="kind"><option value="percent">Porcentaje</option><option value="fixed">Monto fijo</option></select></label><label>Valor<input name="value" type="number" min="1" required></label><label>Compra mínima<input name="min_subtotal_clp" type="number" min="0" value="0"></label><label>Máximo de usos<input name="max_uses" type="number" min="1" placeholder="Sin límite"></label><label>Inicio<input name="starts_at" type="datetime-local"></label><label>Fin<input name="ends_at" type="datetime-local"></label></div><div class="dialog-actions"><button type="button" class="admin-secondary dialog-cancel">Cancelar</button><button type="submit" class="admin-primary">Crear cupón</button></div><p class="admin-form-status" role="alert"></p></form></dialog>`;shell(content,'cupones');wireCoupons()}
function wireCoupons(){const dialog=root.querySelector('#coupon-dialog'),form=root.querySelector('#coupon-form');root.querySelector('#new-coupon').onclick=()=>dialog.showModal();dialog.querySelector('.dialog-close').onclick=()=>dialog.close();dialog.querySelector('.dialog-cancel').onclick=()=>dialog.close();root.querySelectorAll('[data-toggle-coupon]').forEach(button=>button.onclick=async()=>{const coupon=adminData.coupons.find(item=>String(item.id)===button.dataset.toggleCoupon);const {error}=await supabase.from('coupons').update({active:!coupon.active,updated_at:new Date().toISOString()}).eq('id',coupon.id);if(error)return toast(error.message);await refreshData('Cupón actualizado.')});form.onsubmit=async event=>{event.preventDefault();const data=new FormData(form),button=event.submitter,payload={code:String(data.get('code')).trim().toUpperCase().replace(/\s+/g,'-'),description:String(data.get('description')).trim()||null,kind:String(data.get('kind')),value:Number(data.get('value')),min_subtotal_clp:Number(data.get('min_subtotal_clp')||0),max_uses:data.get('max_uses')?Number(data.get('max_uses')):null,starts_at:data.get('starts_at')?new Date(String(data.get('starts_at'))).toISOString():null,ends_at:data.get('ends_at')?new Date(String(data.get('ends_at'))).toISOString():null,active:true};button.disabled=true;const {error}=await supabase.from('coupons').insert(payload);if(error){button.disabled=false;form.querySelector('.admin-form-status').textContent=error.code==='23505'?'Ese código ya existe.':error.message;return}dialog.close();await refreshData('Cupón creado.')}}
function plannedView(route){const label=routes.find(([id])=>id===route)?.[2]||'Sección';const content=`${pageHeading('PRÓXIMA ETAPA',`${label}.`,'La estructura ya está preparada. Activaremos esta vista en una siguiente etapa sin mezclarla con el trabajo actual.')}<section class="admin-panel admin-empty"><strong>${label} todavía no está habilitado.</strong><p>Por ahora puedes trabajar en Resumen, Catálogo y Pedidos.</p><a class="admin-secondary" href="#resumen">Volver al resumen</a></section>`;shell(content,route)}
function render(){const route=currentRoute();if(route==='resumen')summaryView();else if(route==='productos')productsView();else if(route==='colecciones')collectionsView();else if(route==='disenos')designsView();else if(route==='pedidos')ordersView();else if(route==='cupones')couponsView();else plannedView(route)}
async function requestCatalogRebuild(){
 if(import.meta.env.DEV)return {queued:false,local:true};
 const {data:{session}}=await supabase.auth.getSession();
 if(!session?.access_token)throw new Error('La sesión venció. Vuelve a ingresar.');
 const response=await fetch('/api/rebuild-catalog',{method:'POST',headers:{Authorization:`Bearer ${session.access_token}`}});
 const payload=await response.json().catch(()=>({}));
 if(!response.ok)throw new Error(payload.error||'No se pudo iniciar la regeneración SEO.');
 return payload;
}
async function refreshData(message,catalogChanged=false){
 adminData=await readAdminData();render();if(message)toast(message);
 if(!catalogChanged)return;
 try{const rebuild=await requestCatalogRebuild();if(rebuild.queued)toast('Cambio guardado · actualizando páginas SEO.');}
 catch(error){console.error(error);toast('Cambio guardado · publicación SEO pendiente.');}
}
function watchNewOrders(){if(adminOrdersChannel)supabase.removeChannel(adminOrdersChannel);adminOrdersChannel=supabase.channel('admin-new-orders').on('postgres_changes',{event:'INSERT',schema:'public',table:'orders'},()=>refreshData('Llegó un nuevo pedido.')).subscribe()}
async function boot(){loadingView();const {data:{user}}=await supabase.auth.getUser();if(!user)return loginView();const {data:isAdmin,error}=await supabase.rpc('is_admin');if(error||!isAdmin)return deniedView();sessionUser=user;try{await ensureBaseCatalog();adminData=await readAdminData();render();watchNewOrders()}catch(error){root.innerHTML=`<section class="admin-login"><h1>No pudimos cargar el panel.</h1><p class="admin-notice admin-error" role="alert">${safe(error.message)}</p><button class="admin-secondary" id="admin-retry">Reintentar</button></section>`;root.querySelector('#admin-retry').onclick=boot}}
window.addEventListener('hashchange',()=>{if(adminData)render()});
boot();
